import{_ as t,o as a,c as r,a0 as i}from"./chunks/framework.BxrwG5q5.js";const h=JSON.parse('{"title":"Targeting Rules","description":"","frontmatter":{},"headers":[],"relativePath":"features/targeting.md","filePath":"features/targeting.md"}'),l={name:"features/targeting.md"};function s(n,e,o,u,d,g){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="targeting-rules" tabindex="-1">Targeting Rules <a class="header-anchor" href="#targeting-rules" aria-label="Permalink to &quot;Targeting Rules&quot;">​</a></h1><blockquote><p>See also: <a href="/config/features/segments.html">Segments</a> · <a href="/config/features/rollouts.html">Percentage Rollouts</a> · <a href="/config/guide/scopes.html">Configuration Scopes</a></p></blockquote><p>Targeting rules let you serve different config values to different users based on their attributes or <a href="/config/features/segments.html">segment</a> membership.</p><h2 id="how-targeting-works" tabindex="-1">How Targeting Works <a class="header-anchor" href="#how-targeting-works" aria-label="Permalink to &quot;How Targeting Works&quot;">​</a></h2><p>Rules are evaluated in <strong>priority order</strong> (lowest number first). The first rule that matches wins. If no rules match, the default value is returned.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Priority 1: If user in &quot;Beta Users&quot; → value: true</span></span>
<span class="line"><span>Priority 2: If plan equals &quot;enterprise&quot; → value: true</span></span>
<span class="line"><span>Default: false</span></span></code></pre></div><h2 id="two-types-of-rules" tabindex="-1">Two Types of Rules <a class="header-anchor" href="#two-types-of-rules" aria-label="Permalink to &quot;Two Types of Rules&quot;">​</a></h2><h3 id="_1-segment-based-rules-recommended" tabindex="-1">1. Segment-Based Rules (Recommended) <a class="header-anchor" href="#_1-segment-based-rules-recommended" aria-label="Permalink to &quot;1. Segment-Based Rules (Recommended)&quot;">​</a></h3><p>The simplest and most common pattern. Pick segments, assign a value.</p><ul><li>Click <strong>Target Segment</strong></li><li>Select one or more segments (OR logic — user in ANY gets the value)</li><li>Set the return value</li><li>Done. No conditions to configure.</li></ul><h3 id="_2-condition-based-rules-advanced" tabindex="-1">2. Condition-Based Rules (Advanced) <a class="header-anchor" href="#_2-condition-based-rules-advanced" aria-label="Permalink to &quot;2. Condition-Based Rules (Advanced)&quot;">​</a></h3><p>For custom attribute-based logic when you need fine-grained control.</p><ul><li>Click <strong>Custom Condition</strong></li><li>Define conditions: <code>attribute</code> <code>operator</code> <code>value</code></li><li>Add AND conditions within a group</li><li>Add OR groups for alternative matches</li></ul><h2 id="value-type-validation" tabindex="-1">Value Type Validation <a class="header-anchor" href="#value-type-validation" aria-label="Permalink to &quot;Value Type Validation&quot;">​</a></h2><p>The return value input is validated against the config&#39;s type:</p><table tabindex="0"><thead><tr><th>Config Type</th><th>Input</th></tr></thead><tbody><tr><td>Boolean</td><td><code>true</code>/<code>false</code> pill toggle</td></tr><tr><td>Number</td><td>Numeric input only</td></tr><tr><td>String</td><td>Free text</td></tr><tr><td>JSON</td><td>Monospace JSON input</td></tr></tbody></table><p>You can&#39;t accidentally type &quot;hello&quot; as a targeting value for a boolean flag.</p><h2 id="evaluation-order" tabindex="-1">Evaluation Order <a class="header-anchor" href="#evaluation-order" aria-label="Permalink to &quot;Evaluation Order&quot;">​</a></h2><p>When a user requests a config value, the full evaluation pipeline runs:</p><ol><li><strong>Archived</strong> — If flag is archived, return undefined</li><li><strong><a href="/config/features/prerequisites.html">Prerequisites</a></strong> — If required flags aren&#39;t met, return default</li><li><strong>Overrides</strong> — If userId has a specific override, use it</li><li><strong><a href="/config/features/scheduling.html">Schedule</a></strong> — If a scheduled value is active, use it</li><li><strong>Targeting Rules</strong> — Evaluate rules by priority</li><li><strong><a href="/config/features/rollouts.html">Rollout</a></strong> — Apply percentage rollout</li><li><strong>Default</strong> — Return the base value</li></ol><h2 id="server-side-vs-client-side" tabindex="-1">Server-Side vs Client-Side <a class="header-anchor" href="#server-side-vs-client-side" aria-label="Permalink to &quot;Server-Side vs Client-Side&quot;">​</a></h2><ul><li><strong>Client keys (cid_):</strong> Targeting is evaluated on the API server. Your rules are never exposed.</li><li><strong>Server keys (svr_):</strong> Full rules are returned; the SDK evaluates locally using plugins.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/features/segments.html">Segments</a> — Create reusable audience groups for segment-based targeting rules</li><li><a href="/config/features/rollouts.html">Percentage Rollouts</a> — Gradually release features after targeting rules are evaluated</li><li><a href="/config/features/prerequisites.html">Prerequisites</a> — Add flag dependencies that gate targeting evaluation</li><li><a href="/config/features/scheduling.html">Scheduling</a> — Time-based value overrides that sit above targeting in the pipeline</li><li><a href="/config/guide/scopes.html">Configuration Scopes</a> — How context and segments feed into rule evaluation</li></ul>`,24)])])}const f=t(l,[["render",s]]);export{h as __pageData,f as default};
